CREATE TRIGGER IF NOT EXISTS creation_search_events_insert AFTER INSERT ON events BEGIN UPDATE creation_search_partitions SET invalidated=1,index_version=index_version+1 WHERE 'creative:'||owner_id=NEW.stream_id AND (substr(NEW.type,1,5)='Block' OR substr(NEW.type,1,8)='Document' OR substr(NEW.type,1,7)='Project') AND NEW.type NOT IN('ProjectOpened','DocumentOpened') AND (NEW.type='BlockRehomed' OR json_extract(NEW.payload,'$.project_id') IS NULL OR project_id=json_extract(NEW.payload,'$.project_id')); UPDATE creation_search_records SET tombstone=1 WHERE (kind IN('project','document') OR source_id=json_extract(NEW.payload,'$.block_id')) AND NEW.type IN('BlockRemoved','BlockRehomed') AND partition_key IN(SELECT partition_key FROM creation_search_partitions WHERE 'creative:'||owner_id=NEW.stream_id AND (NEW.type='BlockRehomed' OR json_extract(NEW.payload,'$.project_id') IS NULL OR project_id=json_extract(NEW.payload,'$.project_id'))); END;
--> statement-breakpoint
CREATE TRIGGER IF NOT EXISTS creation_search_secrets_insert AFTER INSERT ON event_private_payloads BEGIN UPDATE creation_search_partitions SET invalidated=1,index_version=index_version+1 WHERE 'creative:'||owner_id IN(SELECT stream_id FROM events WHERE event_id=NEW.private_event_id AND (substr(type,1,5)='Block' OR substr(type,1,8)='Document' OR substr(type,1,7)='Project') AND type NOT IN('ProjectOpened','DocumentOpened') AND (events.type='BlockRehomed' OR NOT EXISTS(SELECT 1 FROM json_each(json_array(NEW.project_id,json_extract(CASE WHEN json_valid(NEW.private_json) THEN NEW.private_json ELSE '{}' END,'$.project_id'),json_extract(CASE WHEN json_valid(events.payload) THEN events.payload ELSE '{}' END,'$.project_id'))) claim WHERE claim.type='text' AND claim.value<>'') OR creation_search_partitions.project_id IN(SELECT claim.value FROM json_each(json_array(NEW.project_id,json_extract(CASE WHEN json_valid(NEW.private_json) THEN NEW.private_json ELSE '{}' END,'$.project_id'),json_extract(CASE WHEN json_valid(events.payload) THEN events.payload ELSE '{}' END,'$.project_id'))) claim WHERE claim.type='text' AND claim.value<>''))) OR project_access_id IN(SELECT project_access_id FROM project_event_scopes WHERE event_id=NEW.private_event_id AND EXISTS(SELECT 1 FROM events WHERE event_id=NEW.private_event_id AND (substr(type,1,5)='Block' OR substr(type,1,8)='Document' OR substr(type,1,7)='Project') AND type NOT IN('ProjectOpened','DocumentOpened'))); END;
